create table cambios_estado_pedido (fecha_hora timestamp(6) not null, id bigint generated by default as identity, pedido_id bigint not null, estado_anterior varchar(20) not null check (estado_anterior in ('RECIBIDO','EN_PREPARACION','LISTO','ENTREGADO')), estado_nuevo varchar(20) not null check (estado_nuevo in ('RECIBIDO','EN_PREPARACION','LISTO','ENTREGADO')), usuario_responsable varchar(100) not null, primary key (id));
create table cuentas (cuenta_abierta boolean generated always as (case when estado = 'ABIERTA' then true else null end) stored, fecha_apertura timestamp(6) not null, fecha_cierre timestamp(6), id bigint generated by default as identity, mesa_id bigint not null, estado varchar(20) not null check (estado in ('ABIERTA','CERRADA')), primary key (id), constraint uk_cuentas_mesa_abierta unique (mesa_id, cuenta_abierta));
create table ingredientes (disponible boolean not null, id bigint generated by default as identity, nombre varchar(100) not null unique, primary key (id));
create table items_pedido (bebida_incluida boolean not null, cantidad integer not null, combo boolean not null, precio_congelado numeric(10,2) not null, id bigint generated by default as identity, pedido_id bigint not null, plato_id bigint not null, nombre_plato varchar(100) not null, primary key (id));
create table mesas (numero integer not null, id bigint generated by default as identity, primary key (id), constraint uk_mesas_numero unique (numero));
create table pagos (monto numeric(12,2) not null, cuenta_id bigint not null unique, fecha_hora timestamp(6) not null, id bigint generated by default as identity, primary key (id));
create table pedidos (confirmado boolean not null, cuenta_id bigint not null, fecha_confirmacion timestamp(6), fecha_creacion timestamp(6) not null, id bigint generated by default as identity, estado varchar(20) not null check (estado in ('RECIBIDO','EN_PREPARACION','LISTO','ENTREGADO')), primary key (id));
create table plato_ingredientes (ingrediente_id bigint not null, plato_id bigint not null);
create table platos (activo boolean not null, combo boolean not null, precio numeric(10,2) not null, id bigint generated by default as identity, nombre varchar(100) not null unique, descripcion varchar(1000), primary key (id));
alter table if exists cambios_estado_pedido add constraint FK8u2yj7srp4y2kh5gr90br53yq foreign key (pedido_id) references pedidos;
alter table if exists cuentas add constraint FKj1fbfcu67s9sokoyg9twubbdw foreign key (mesa_id) references mesas;
alter table if exists items_pedido add constraint FKhshdf36fo6kflmxhom10pbn39 foreign key (pedido_id) references pedidos;
alter table if exists pagos add constraint FK71g2yypobqfloe5bu21rf0uh5 foreign key (cuenta_id) references cuentas;
alter table if exists pedidos add constraint FKljc033ed8j4ugmqjkte1sfo6y foreign key (cuenta_id) references cuentas;
alter table if exists plato_ingredientes add constraint FKljiap0f8lbt8sqa27v62fy2pr foreign key (ingrediente_id) references ingredientes;
alter table if exists plato_ingredientes add constraint FKe6xae1mknu5dv1xeiaqg5e4yg foreign key (plato_id) references platos;
